 struct State{monitors:Vec<Monitor>,error:Option<Error>}
 unsafe extern "system" fn visit(monitor:HMONITOR,_:HDC,_:*mut RECT,data:LPARAM)->BOOL{let state=unsafe{&mut*(data.0 as *mut State)};if state.monitors.len()>=64{state.error=Some(Error::Invalid("projector monitor count64"));return BOOL(0);}let mut info=MONITORINFOEXW::default();info.monitorInfo.cbSize=std::mem::size_of::<MONITORINFOEXW>()as u32;if !unsafe{GetMonitorInfoW(monitor,&mut info as *mut _ as *mut _)}.as_bool(){state.error=Some(Error::Backend(windows::core::Error::from_win32().to_string()));return BOOL(0);}let device=text(&info.szDevice);let mut display=DISPLAY_DEVICEW::default();display.cb=std::mem::size_of::<DISPLAY_DEVICEW>()as u32;let found=unsafe{EnumDisplayDevicesW(PCWSTR(info.szDevice.as_ptr()),0,&mut display,EDD_GET_DEVICE_INTERFACE_NAME)}.as_bool();let name=if found&&!text(&display.DeviceString).is_empty(){text(&display.DeviceString)}else{device.clone()};let id=if found&&!text(&display.DeviceID).is_empty(){text(&display.DeviceID)}else{device};if id.is_empty()||name.is_empty()||state.monitors.iter().any(|m|m.id==id){state.error=Some(Error::Invalid("projector monitor identity/name unavailable or duplicated"));return BOOL(0);}let r=info.monitorInfo.rcMonitor;let(w,h)=(r.right-r.left,r.bottom-r.top);if w<=0||h<=0{state.error=Some(Error::Invalid("projector monitor bounds"));return BOOL(0);}let(mut x,mut y)=(0,0);let scale=unsafe{GetDpiForMonitor(monitor,MDT_EFFECTIVE_DPI,&mut x,&mut y)}.ok().filter(|_|x>0&&x==y).map(|_|x as f32/96.0);state.monitors.push(Monitor{id,name,x:r.left,y:r.top,width:w as u32,height:h as u32,scale,primary:info.monitorInfo.dwFlags&MONITORINFOF_PRIMARY!=0});BOOL(1)}
